package android.app; public class NotificationChannel { private final String id,name; private int importance; private String description; private boolean vibrate=false; public NotificationChannel(String id,String name,int importance){this.id=id;this.name=name;this.importance=importance;} public String getId(){return id;} public int getImportance(){return importance;} public void setImportance(int i){importance=i;} public void setDescription(String d){description=d;} public CharSequence getName(){return name;} public String getDescription(){return description;} public void enableVibration(boolean v){vibrate=v;} public boolean shouldVibrate(){return vibrate;} }
